const state = { user: null, dashboard: null, notifications: [], source: null, currentView: "overview", reportMonth: null, verificationFilter: "active", generatedVerification: null, discountAudience: "public", discountRecipients: [], discountCustomerResults: [] };
const $ = (selector) => document.querySelector(selector);
const loginView = $("#login-view");
const adminView = $("#admin-view");
const content = $("#workspace-content");
const message = $("#site-message");
const loginForm = $("#login-form");
const setupForm = $("#setup-form");

function escapeHtml(value) { return String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", "'":"&#39;", '"':"&quot;" }[char])); }
function arabicNumber(value) { return new Intl.NumberFormat("ar-SY").format(Number(value || 0)); }
function money(value) { return `${arabicNumber(value)} ل.س`; }
function dateLabel(value) { return value ? new Intl.DateTimeFormat("ar-SY", { dateStyle:"medium", timeStyle:"short" }).format(new Date(value)) : "—"; }
function statusTone(status) { return ["requested", "pending", "pending_admin", "code_sent", "locked"].includes(status) ? "warning" : ["delivered", "approved", "ready", "download_confirmed", "verified"].includes(status) ? "success" : ""; }
function statusLabel(status) { const map = { requested:"بانتظار سائق", accepted:"تم القبول", arriving:"في الطريق", awaiting_otp:"بانتظار الرمز", delivered:"مكتمل", cancelled:"ملغى", pending:"معلّق", pending_admin:"بانتظار مراجعة المدير", code_sent:"أُرسل الرمز", locked:"محاولات كثيرة", verified:"متحقق", expired:"منتهي", rejected:"مرفوض", approved:"موافق", ready:"جاهز", download_confirmed:"تم التنزيل", generating:"قيد الإنشاء", purged:"مؤرشف" }; return map[status] || status; }
function orderFinance(order) { const grossAmount = Number(order.final_price ?? order.estimated_price ?? 0); if (order.commission_calculated_at) return { grossAmount, companyCommissionAmount: Number(order.company_commission_amount ?? 0), driverNetAmount: Number(order.driver_net_amount ?? 0) }; const companyCommissionAmount = Math.floor((grossAmount * 3) / 100); return { grossAmount, companyCommissionAmount, driverNetAmount: grossAmount - companyCommissionAmount }; }
function notify(text, isError = false) { message.textContent = text; message.className = `site-message${isError ? " error" : ""}`; message.hidden = false; window.setTimeout(() => { message.hidden = true; }, 6000); }
async function api(url, options = {}) { const response = await fetch(url, { credentials:"same-origin", headers:{ "Content-Type":"application/json", ...(options.headers || {}) }, ...options }); const data = await response.json().catch(() => ({})); if (!response.ok) { const error = new Error(data.error || "REQUEST_FAILED"); error.status = response.status; throw error; } return data; }
function showLoading() { content.innerHTML = $("#loading-template").innerHTML; }
function activateView(view) { state.currentView = view; document.querySelectorAll(".nav-link").forEach((item) => item.classList.toggle("active", item.dataset.view === view)); const titles = { overview:"نظرة عامة", operations:"الطلبات والسفراء", verifications:"طلبات التحقق", accounts:"الحسابات والوثائق", discounts:"رموز الخصم", reports:"التقارير المالية", settlements:"تسويات السفراء", archives:"الأرشفة اليدوية", release:"تحديث التطبيق" }; $("#page-title").textContent = titles[view] || "بوابة الإدارة"; if (view === "overview") renderOverview(); if (view === "operations") renderOperations(); if (view === "verifications") renderVerificationWorkspace(); if (view === "accounts") renderAccounts(); if (view === "discounts") renderDiscounts(); if (view === "reports") renderReports(); if (view === "settlements") renderSettlements(); if (view === "archives") renderArchives(); if (view === "release") renderRelease(); }

function renderOverview() { const data = state.dashboard; if (!data) return showLoading(); const metrics = data.metrics; const orders = data.orders || []; const drivers = data.drivers || []; content.innerHTML = `
  <section class="hero"><div><p class="eyebrow">تشغيل اليوم</p><h2>صباح الخير، ${escapeHtml(state.user.name)}</h2><p>نظرة مستقلة على عمليات التوصيل؛ لا تتطلب فتح تطبيق الهاتف.</p></div><div class="date-stamp">${new Intl.DateTimeFormat("ar-SY", { weekday:"long", day:"numeric", month:"long", year:"numeric" }).format(new Date())}</div></section>
  <section class="metric-grid"><article class="metric-card"><span class="label">طلبات اليوم</span><strong>${arabicNumber(metrics.todayOrders)}</strong><small>حركة اليوم الحالية</small></article><article class="metric-card green"><span class="label">سائقون نشطون</span><strong>${arabicNumber(metrics.activeDrivers)}</strong><small>ضمن الحسابات المفعلة</small></article><article class="metric-card amber"><span class="label">طلبات التفعيل</span><strong>${arabicNumber(metrics.pendingDrivers)}</strong><small>تحتاج قرار الإدارة</small></article><article class="metric-card blue"><span class="label">إجمالي تحصيل المكتمل</span><strong>${money(metrics.grossRevenue)}</strong><small>${arabicNumber(metrics.completedTrips)} رحلة مكتملة</small></article><article class="metric-card amber"><span class="label">عمولة جربوع 3%</span><strong>${money(metrics.companyCommission)}</strong><small>مثبتة عند التسليم</small></article><article class="metric-card green"><span class="label">صافي مستحق السفراء</span><strong>${money(metrics.driverNetAmount)}</strong><small>بعد عمولة الشركة</small></article><article class="metric-card"><span class="label">ورديات مفتوحة</span><strong>${arabicNumber(metrics.openShifts)}</strong><small>تحتاج تسوية لاحقاً</small></article></section>
  <section class="dashboard-grid"><article class="card"><div class="card-head"><div><h3>توزع الأسطول</h3><p>آخر مواقع السائقين المفعّلين</p></div><span class="badge success">${arabicNumber(drivers.length)} متصلون</span></div><div class="map-panel"><b class="map-label">حماة</b><i class="map-pin one">س</i><i class="map-pin two active">ف</i><i class="map-pin three">م</i><span class="map-legend">تحديث موقع السائقين نشط</span></div></article><article class="card"><div class="card-head"><div><h3>تنبيهات تحتاج متابعة</h3><p>آخر الطلبات وتغيّرات السائقين</p></div><button class="text-button" data-action="open-notices">عرض الكل</button></div><div class="action-list">${state.notifications.slice(0,3).map((item) => `<div class="action-item"><i class="round-icon ${item.level === "warning" ? "amber" : item.level === "success" ? "green" : ""}">${item.kind === "order" ? "#" : "س"}</i><div><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.detail)}</span></div><span class="badge ${item.level === "warning" ? "warning" : item.level === "success" ? "success" : ""}">${dateLabel(item.createdAt)}</span></div>`).join("") || `<p class="empty">لا توجد تنبيهات حالياً.</p>`}</div></article></section>
  <section class="card" style="margin-top:16px"><div class="card-head"><div><h3>آخر الطلبات</h3><p>آخر تحديثات حالة التوصيل</p></div><button class="text-button" data-view-link="operations">إدارة العمليات</button></div><table class="data-table"><thead><tr><th>الطلب والمسار</th><th>الحالة</th><th>السائق</th><th>آخر تحديث</th></tr></thead><tbody>${orders.map((order) => `<tr><td><strong>#${escapeHtml(order.id.slice(0,8))}</strong><small>${escapeHtml(order.source_address)} ← ${escapeHtml(order.destination_address)}</small></td><td><span class="badge ${statusTone(order.status)}">${statusLabel(order.status)}</span></td><td>${order.driver_id ? "مُعيّن" : "—"}</td><td>${dateLabel(order.updated_at)}</td></tr>`).join("") || `<tr><td colspan="4" class="empty">لا توجد طلبات مسجلة.</td></tr>`}</tbody></table></section><p class="data-note">تعرض البوابة بيانات محفوظة على الخادم وتتحقق من صلاحية المدير لكل طلب.</p>`;
  bindContentActions(); }
function renderOperations() { const data = state.dashboard; const pending = state.notifications.filter((n) => n.kind === "driver"); content.innerHTML = `<section class="hero"><div><p class="eyebrow">إدارة مباشرة</p><h2>الطلبات والسائقون</h2><p>تُظهر تسوية الطلب المكتمل إجمالي التحصيل وعمولة الشركة وصافي السفير.</p></div></section><section class="operations-layout"><article class="card"><div class="card-head"><div><h3>سجل الطلبات</h3><p>أحدث ما وصل إلى منصة التوصيل</p></div><span class="badge warning">${arabicNumber((data.orders || []).filter((o) => o.status === "requested").length)} بانتظار تعيين</span></div><table class="data-table"><thead><tr><th>المعرف</th><th>المسار</th><th>التسوية المالية</th><th>الحالة</th></tr></thead><tbody>${(data.orders || []).map((order) => { const finance = orderFinance(order); const settlement = order.status === "delivered" ? `<strong>الإجمالي: ${money(finance.grossAmount)}</strong><small>عمولة جربوع: ${money(finance.companyCommissionAmount)} · صافي السفير: ${money(finance.driverNetAmount)}</small>` : `<strong>${money(finance.grossAmount)}</strong><small>تُثبت العمولة عند التسليم</small>`; return `<tr><td><strong>#${escapeHtml(order.id.slice(0,8))}</strong></td><td>${escapeHtml(order.source_address)}<small>${escapeHtml(order.destination_address)}</small></td><td>${settlement}</td><td><span class="badge ${statusTone(order.status)}">${statusLabel(order.status)}</span></td></tr>`; }).join("") || `<tr><td colspan="4" class="empty">لا توجد طلبات بعد.</td></tr>`}</tbody></table></article><section class="split-card"><article class="card"><div class="card-head"><div><h3>سائقون مفعّلون</h3><p>الحسابات النشطة</p></div><span class="badge success">${arabicNumber((data.drivers || []).length)} نشطون</span></div><div class="action-list">${(data.drivers || []).map((driver) => `<div class="action-item"><i class="round-icon green">${escapeHtml((driver.name || "س").slice(0,1))}</i><div><strong>${escapeHtml(driver.name || "سائق جربوع")}</strong><span>${driver.last_location_at ? `آخر موقع: ${dateLabel(driver.last_location_at)}` : "لم يرسل الموقع بعد"}</span></div><span class="badge success">مفعّل</span></div>`).join("") || `<p class="empty">لا يوجد سائقون نشطون.</p>`}</div></article><article class="card"><div class="card-head"><div><h3>ملفات التحقق</h3><p>آخر تغيرات ملفات السائقين</p></div></div><div class="action-list">${pending.map((item) => `<div class="action-item"><i class="round-icon amber">س</i><div><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.detail)}</span></div><span class="badge warning">معلّق</span></div>`).join("") || `<p class="empty">لا توجد ملفات معلقة.</p>`}</div></article></section></section>`; }
async function renderVerifications() { showLoading(); try { const result = await api("/admin/api/verifications"); const requests = result.requests || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">دخول برمز تحقق</p><h2>طلبات العميل والسفير</h2><p>أنشئ الرمز هنا ثم افتح WhatsApp لإرساله يدوياً إلى الرقم المسجل. لا يُحفظ الرمز كنص صريح في النظام.</p></div></section><section class="card"><div class="card-head"><div><h3>طلبات بانتظار المراجعة</h3><p>الرمز صالح عشر دقائق فقط وتظهر بيانات كل متقدم للمديرين المصرح لهم.</p></div><span class="badge warning">${arabicNumber(requests.length)} طلبات</span></div><div class="action-list">${requests.map((request) => `<div class="action-item"><i class="round-icon ${request.requested_role === "driver" ? "amber" : "green"}">${request.requested_role === "driver" ? "س" : "ع"}</i><div><strong>${escapeHtml(request.full_name)} · ${request.requested_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(request.phone)}${request.vehicle_type ? ` · ${escapeHtml(request.vehicle_type)}` : ""} · ${statusLabel(request.status)}</span></div><button class="small-action" data-verification-id="${escapeHtml(request.id)}">${request.status === "code_sent" ? "إعادة إرسال الرمز" : "إرسال الرمز عبر WhatsApp"}</button></div>`).join("") || `<p class="empty">لا توجد طلبات تحقق معلقة.</p>`}</div></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }
async function renderReports() { showLoading(); try { const defaultMonth = new Date(new Date().setMonth(new Date().getMonth()-1)).toISOString().slice(0,7); const month = state.reportMonth || defaultMonth; const result = await api(`/admin/api/reports?reportMonth=${encodeURIComponent(`${month}-01`)}`); const reports = result.reports || []; const finance = result.financialSummary || { completedTrips:0, grossRevenue:0, companyCommission:0, driverNetAmount:0 }; content.innerHTML = `<section class="hero"><div><p class="eyebrow">تقارير وأرشفة</p><h2>التقارير المالية والتشغيلية</h2><p>عمولة الشركة ثابتة عند 3% من السعر النهائي بعد الخصم لكل رحلة مكتملة.</p></div></section><section class="reports-layout"><article class="card"><div class="card-head"><div><h3>إنشاء تقرير شهري</h3><p>تجميع الطلبات والورديات في ملف PDF قابل للتحميل.</p></div><span class="badge">PDF</span></div><div class="report-controls"><label>الشهر<div><input id="report-month" type="month" value="${escapeHtml(month)}" /></div></label><button id="generate-report" class="primary-button" type="button">إنشاء أو تحديث التقرير</button></div><p class="security-note">يمكن للمدير المصرح فقط إنشاء التقرير أو تنزيله، وتسجل المنصة تأكيد التنزيل قبل أي أرشفة لاحقة.</p></article><article class="card"><div class="card-head"><div><h3>ملخص ${escapeHtml(month)}</h3><p>رحلات مكتملة خلال الشهر المحدد، وفق وقت التسليم.</p></div><span class="badge success">${arabicNumber(finance.completedTrips)} رحلة</span></div><div class="action-list"><div class="action-item"><i class="round-icon blue">إ</i><div><strong>إجمالي التحصيل</strong><span>السعر النهائي المدفوع بعد الخصم</span></div><strong>${money(finance.grossRevenue)}</strong></div><div class="action-item"><i class="round-icon amber">٪</i><div><strong>عمولة جربوع 3%</strong><span>مُثبتة لكل رحلة وقت تأكيد التسليم</span></div><strong>${money(finance.companyCommission)}</strong></div><div class="action-item"><i class="round-icon green">س</i><div><strong>صافي مستحق السفراء</strong><span>الإجمالي بعد طرح عمولة الشركة</span></div><strong>${money(finance.driverNetAmount)}</strong></div></div></article></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>ملفات PDF المتاحة</h3><p>يتضمن كل ملف إجمالي التحصيل والعمولة وصافي السفير للرحلات المكتملة.</p></div><span class="badge success">${arabicNumber(reports.length)} تقارير</span></div><div>${reports.map((report) => `<div class="report-row"><div><strong>${escapeHtml(String(report.report_month).slice(0,7))}</strong><span>${report.generated_at ? `أُنشئ: ${dateLabel(report.generated_at)}` : "بانتظار الإنشاء"}</span></div><span class="badge ${statusTone(report.status)}">${statusLabel(report.status)}</span><button class="download-link" data-report-id="${escapeHtml(report.id)}" ${["ready","download_confirmed"].includes(report.status) ? "" : "disabled"}>تنزيل PDF</button></div>`).join("") || `<p class="empty">لا توجد تقارير جاهزة بعد. اختر شهراً لإنشاء التقرير.</p>`}</div></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

async function renderSettlements() { showLoading(); try { const result = await api("/admin/api/driver-company-balances"); const balances = result.balances || []; const totalOutstanding = balances.reduce((sum, row) => sum + Number(row.outstanding_amount || 0), 0); const totalPaid = balances.reduce((sum, row) => sum + Number(row.paid_amount || 0), 0); content.innerHTML = `<section class="hero"><div><p class="eyebrow">تحصيل عمولة الشركة</p><h2>تسويات السفراء النقدية</h2><p>التسوية المتاحة حالياً هي Cash فقط: تستلم المبلغ يدوياً من السفير ثم تسجل الدفعة. يتراكم الرصيد من جديد تلقائياً مع الرحلات التالية.</p></div></section><section class="metric-grid"><article class="metric-card amber"><span class="label">إجمالي المتبقي للشركة</span><strong>${money(totalOutstanding)}</strong><small>على جميع السفراء</small></article><article class="metric-card green"><span class="label">إجمالي الدفعات النقدية</span><strong>${money(totalPaid)}</strong><small>استلام يدوي مسجل</small></article><article class="metric-card blue"><span class="label">عدد السفراء</span><strong>${arabicNumber(balances.length)}</strong><small>تظهر الأرصدة المحدثة</small></article></section><section class="card"><div class="card-head"><div><h3>كشف كل سفير</h3><p>استخدم «تعبئة المتبقي» بعد استلام المبلغ نقداً لتصفير الرصيد؛ يبدأ التراكم من جديد مع أي رحلة مكتملة لاحقة.</p></div><span class="badge success">Cash متاح</span></div><table class="data-table"><thead><tr><th>السفير</th><th>عمولة الرحلات</th><th>المدفوع</th><th>المتبقي</th><th>تسجيل استلام Cash</th></tr></thead><tbody>${balances.map((row) => { const outstanding = Number(row.outstanding_amount || 0); return `<tr><td><strong>${escapeHtml(row.driver_name || "سفير جربوع")}</strong><small>${Number(row.payment_count || 0) ? `${arabicNumber(row.payment_count)} دفعات · آخرها ${dateLabel(row.last_payment_at)}` : "لا توجد دفعات مسجلة"}</small></td><td>${money(row.total_commission_amount)}</td><td>${money(row.paid_amount)}</td><td><strong>${money(outstanding)}</strong><small>${outstanding === 0 ? "تمت التسوية" : "مستحق للشركة"}</small></td><td>${outstanding === 0 ? `<span class="badge success">الرصيد صفر</span>` : `<form class="driver-payment-form report-controls" data-driver-id="${escapeHtml(row.driver_id)}"><label>المبلغ المستلم نقداً<input name="amount" type="number" min="1" max="${escapeHtml(outstanding)}" step="1" required /></label><label>ملاحظة (اختيارية)<input name="note" maxlength="500" placeholder="مثال: استلام آخر الأسبوع" /></label><button class="small-action" type="button" data-fill-outstanding="${escapeHtml(outstanding)}">تعبئة المتبقي</button><button class="primary-button" type="submit">تأكيد استلام Cash</button></form>`}</td></tr>`; }).join("") || `<tr><td colspan="5" class="empty">لا توجد حسابات سفراء بعد.</td></tr>`}</tbody></table></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

async function renderVerifications() { showLoading(); try { const [verificationResult, recoveryResult] = await Promise.all([api("/admin/api/verifications"), api("/admin/api/recovery-requests")]); const requests = verificationResult.requests || []; const recoveries = recoveryResult.requests || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">تحقق WhatsApp</p><h2>طلبات التسجيل والاسترجاع</h2><p>راجع بيانات العميل أو السفير، ثم افتح WhatsApp بالرسالة الجاهزة. لا يظهر الرمز في النظام بعد فتح الرسالة.</p></div></section><section class="card"><div class="card-head"><div><h3>طلبات التسجيل</h3><p>وثائق السفير خاصة ولا يراها إلا مدير الموقع.</p></div><span class="badge warning">${arabicNumber(requests.length)} طلبات</span></div><div class="action-list">${requests.map((request) => `<div class="action-item"><i class="round-icon ${request.requested_role === "driver" ? "amber" : "green"}">${request.requested_role === "driver" ? "س" : "ع"}</i><div><strong>${escapeHtml(request.full_name)} · ${request.requested_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(request.phone)} · ${statusLabel(request.status)}</span>${request.requested_role === "driver" ? `<span><button class="text-button" data-pending-document="personal" data-request-id="${escapeHtml(request.id)}">الصورة الشخصية</button><button class="text-button" data-pending-document="identity" data-request-id="${escapeHtml(request.id)}">صورة الهوية</button></span>` : ""}</div><button class="small-action" data-verification-id="${escapeHtml(request.id)}">${request.status === "code_sent" ? "إعادة إرسال الرمز" : "إرسال الرمز"}</button></div>`).join("") || `<p class="empty">لا توجد طلبات تسجيل معلقة.</p>`}</div></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>استرجاع كلمات المرور</h3><p>يتحقق التطبيق من الاسم والرقم، ثم يغير المستخدم كلمة المرور بعد رمز WhatsApp.</p></div><span class="badge warning">${arabicNumber(recoveries.length)} طلبات</span></div><div class="action-list">${recoveries.map((request) => `<div class="action-item"><i class="round-icon amber">↺</i><div><strong>${escapeHtml(request.full_name)} · ${request.requested_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(request.phone)} · ${statusLabel(request.status)}</span></div><button class="small-action" data-recovery-id="${escapeHtml(request.id)}">${request.status === "code_sent" ? "إعادة إرسال الرمز" : "إرسال رمز الاسترجاع"}</button></div>`).join("") || `<p class="empty">لا توجد طلبات استرجاع معلقة.</p>`}</div></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

function isExpiredVerification(request) { return request.status === "expired" || Boolean(request.code_expires_at && new Date(request.code_expires_at).getTime() <= Date.now()); }
function verificationRequestRow(request) { const expired = isExpiredVerification(request); const status = expired ? "expired" : request.status; return `<div class="action-item"><i class="round-icon ${request.requested_role === "driver" ? "amber" : "green"}">${request.requested_role === "driver" ? "س" : "ع"}</i><div><strong>${escapeHtml(request.full_name)} · ${request.requested_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(request.phone)} · ${statusLabel(status)}${request.code_expires_at ? ` · ${expired ? "انتهى" : "ينتهي"}: ${dateLabel(request.code_expires_at)}` : ""}</span></div>${expired ? `<button class="small-action" data-delete-expired-verification="${escapeHtml(request.id)}">حذف الطلب المنتهي</button>` : `<button class="small-action" data-verification-id="${escapeHtml(request.id)}">${request.status === "code_sent" ? "إعادة توليد الرمز" : "توليد رمز جديد"}</button>`}</div>`; }
function bindVerificationWorkspaceActions() { const filter = $("#verification-filter"); if (filter) filter.addEventListener("change", () => { state.verificationFilter = filter.value; renderVerificationWorkspace(); }); document.querySelectorAll("[data-delete-expired-verification]").forEach((button) => button.addEventListener("click", () => deleteExpiredVerification(button.dataset.deleteExpiredVerification, button))); const copyButton = $("#copy-generated-code"); if (copyButton) copyButton.addEventListener("click", () => { const code = state.generatedVerification?.code; if (!code) return; navigator.clipboard?.writeText(code).catch(() => {}); notify("تمت محاولة نسخ الرمز. يمكنك نسخه أيضاً من الرقم الظاهر."); }); const whatsappButton = $("#open-generated-whatsapp"); if (whatsappButton) whatsappButton.addEventListener("click", () => { const url = state.generatedVerification?.whatsappUrl; if (url) window.open(url, "_blank", "noopener,noreferrer"); }); }
async function deleteExpiredVerification(requestId, button) { if (!requestId || !window.confirm("حذف طلب تحقق منتهٍ نهائياً؟ لا يمكن استعادته.")) return; button.disabled = true; button.textContent = "جارٍ الحذف…"; try { await api(`/admin/api/verifications/${encodeURIComponent(requestId)}`, { method:"DELETE" }); notify("حُذف طلب التحقق المنتهي ووثائقه الخاصة إن وُجدت."); await renderVerificationWorkspace(); } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "حذف الطلب المنتهي"; } }
async function renderVerificationWorkspace() { showLoading(); try { const [verificationResult, recoveryResult] = await Promise.all([api("/admin/api/verifications"), api("/admin/api/recovery-requests")]); const requests = verificationResult.requests || []; const recoveries = recoveryResult.requests || []; const active = requests.filter((request) => !isExpiredVerification(request)); const expired = requests.filter(isExpiredVerification); const shown = state.verificationFilter === "expired" ? expired : state.verificationFilter === "all" ? requests : active; const generated = state.generatedVerification; const codeCard = generated ? `<section class="card" style="margin-bottom:16px;border:2px solid #1f7a5b"><div class="card-head"><div><p class="eyebrow">رمز مولّد الآن</p><h3>انسخ الرمز أو أرسله متى تريد</h3><p>هذا الرقم هو نفسه الذي خزّنه الخادم للتحقق، وينتهي في ${dateLabel(generated.expiresAt)}.</p></div><span class="badge success">صالح</span></div><div class="report-controls"><label>رمز التحقق<input value="${escapeHtml(generated.code)}" readonly aria-label="رمز التحقق المولّد" /></label><button id="copy-generated-code" class="primary-button" type="button">نسخ الرمز</button><button id="open-generated-whatsapp" class="small-action" type="button">فتح WhatsApp لإرسال الرمز</button></div><p class="security-note">فتح WhatsApp اختياري؛ لا يُفتح تلقائياً ولا يُحفظ الرمز كنص في قاعدة البيانات.</p></section>` : `<section class="card" style="margin-bottom:16px"><p class="security-note">لتوليد رمز: اختر طلباً ثم اضغط «توليد رمز جديد». يظهر الرمز هنا أولاً، وبعدها تختار بنفسك إن كنت تريد فتح WhatsApp.</p></section>`; content.innerHTML = `<section class="hero"><div><p class="eyebrow">تحقق WhatsApp</p><h2>طلبات التسجيل والاسترجاع</h2><p>يظهر رمز التسجيل في هذه الصفحة أولاً. افتح WhatsApp فقط عندما ترغب بإرسال الرسالة.</p></div></section>${codeCard}<section class="card"><div class="card-head"><div><h3>طلبات التسجيل</h3><p>يمكن حذف الطلبات المنتهية فقط. الطلبات الصالحة لا يظهر لها زر حذف.</p></div><label>عرض الطلبات<select id="verification-filter"><option value="active" ${state.verificationFilter === "active" ? "selected" : ""}>الصالحة فقط (${arabicNumber(active.length)})</option><option value="expired" ${state.verificationFilter === "expired" ? "selected" : ""}>المنتهية فقط (${arabicNumber(expired.length)})</option><option value="all" ${state.verificationFilter === "all" ? "selected" : ""}>الكل (${arabicNumber(requests.length)})</option></select></label></div><div class="action-list">${shown.map(verificationRequestRow).join("") || `<p class="empty">لا توجد طلبات ضمن هذه التصفية.</p>`}</div></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>استرجاع كلمات المرور</h3><p>ينشئ الرمز ويعرضه بنفس التدفق قبل فتح WhatsApp اختيارياً.</p></div><span class="badge warning">${arabicNumber(recoveries.length)} طلبات</span></div><div class="action-list">${recoveries.map((request) => `<div class="action-item"><i class="round-icon amber">↺</i><div><strong>${escapeHtml(request.full_name)} · ${request.requested_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(request.phone)} · ${statusLabel(request.status)}</span></div><button class="small-action" data-recovery-id="${escapeHtml(request.id)}">${request.status === "code_sent" ? "إعادة توليد الرمز" : "توليد رمز الاسترجاع"}</button></div>`).join("") || `<p class="empty">لا توجد طلبات استرجاع معلقة.</p>`}</div></section>`; bindContentActions(); bindVerificationWorkspaceActions(); } catch (error) { handleApiError(error); } }
async function renderAccounts() { showLoading(); try { const result = await api("/admin/api/accounts"); const accounts = result.accounts || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">إدارة الحسابات</p><h2>العملاء والسفراء والوثائق</h2><p>إيقاف الحساب يمنع الدخول ويحافظ على سجل تسجيل الدخول والبيانات الأساسية وفق سياسة الأرشفة.</p></div></section><section class="card"><div class="card-head"><div><h3>الحسابات المسجلة</h3><p>معاينة الوثائق بروابط خاصة مؤقتة.</p></div><span class="badge">${arabicNumber(accounts.length)} حسابات</span></div><table class="data-table"><thead><tr><th>الحساب</th><th>الرقم</th><th>الحالة</th><th>الوثائق</th><th>إجراء</th></tr></thead><tbody>${accounts.map((account) => `<tr><td><strong>${escapeHtml(account.name)}</strong><small>${account.role === "driver" ? "سفير" : "عميل"} · ${dateLabel(account.created_at)}</small></td><td>${escapeHtml(account.phone || "—")}</td><td><span class="badge ${account.is_active ? "success" : "warning"}">${account.is_active ? "نشط" : "موقوف"}</span></td><td>${account.role === "driver" ? `<button class="text-button" data-account-document="personal" data-account-id="${escapeHtml(account.id)}">شخصية</button><button class="text-button" data-account-document="identity" data-account-id="${escapeHtml(account.id)}">هوية</button>` : "—"}</td><td><button class="small-action" data-account-toggle="${escapeHtml(account.id)}" data-account-active="${account.is_active ? "true" : "false"}">${account.is_active ? "إيقاف الحساب" : "إعادة التفعيل"}</button></td></tr>`).join("") || `<tr><td colspan="5" class="empty">لا توجد حسابات بعد.</td></tr>`}</tbody></table></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

async function renderDiscounts() { showLoading(); try { const result = await api("/admin/api/discounts"); const codes = result.codes || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">عروض العملاء</p><h2>رموز الخصم</h2><p>تُحسب قيمة الخصم من الخادم عند إنشاء طلب العميل، ولا تظهر هذه الرموز في مساحة السفير.</p></div></section><section class="reports-layout"><article class="card"><div class="card-head"><div><h3>إنشاء رمز جديد</h3><p>اختر خصماً ثابتاً أو نسبة مئوية وفترة اختيارية.</p></div></div><form id="discount-form" class="report-controls"><label>الرمز<input id="discount-code" required maxlength="32" placeholder="JARBOU3" /></label><label>النوع<select id="discount-type"><option value="fixed">قيمة ثابتة</option><option value="percentage">نسبة مئوية</option></select></label><label>القيمة<input id="discount-value" type="number" min="1" step="1" required /></label><label>يبدأ (اختياري)<input id="discount-start" type="datetime-local" /></label><label>ينتهي (اختياري)<input id="discount-end" type="datetime-local" /></label><button class="primary-button" type="submit">حفظ الرمز</button></form></article><article class="card"><div class="card-head"><div><h3>الرموز الحالية</h3><p>يمكن إيقاف أي رمز يدوياً في الحال.</p></div><span class="badge">${arabicNumber(codes.length)} رموز</span></div><div class="action-list">${codes.map((code) => `<div class="action-item"><i class="round-icon ${code.is_active ? "green" : "amber"}">٪</i><div><strong>${escapeHtml(code.code)} · ${code.discount_type === "percentage" ? `${arabicNumber(code.discount_value)}%` : money(code.discount_value)}</strong><span>${code.starts_at ? `يبدأ: ${dateLabel(code.starts_at)}` : "يبدأ فوراً"} · ${code.ends_at ? `ينتهي: ${dateLabel(code.ends_at)}` : "دون نهاية"}</span></div><button class="small-action" data-discount-toggle="${escapeHtml(code.id)}" data-discount-active="${code.is_active ? "true" : "false"}">${code.is_active ? "إيقاف" : "تفعيل"}</button></div>`).join("") || `<p class="empty">لا توجد رموز خصم بعد.</p>`}</div></article></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

async function renderArchives() { showLoading(); try { const result = await api("/admin/api/manual-archives"); const archives = result.archives || []; const today = new Date().toISOString().slice(0,10); content.innerHTML = `<section class="hero"><div><p class="eyebrow">أرشفة وحذف يدوي</p><h2>حماية السعة التخزينية</h2><p>أنشئ PDF، نزّله، ثم اكتب DELETE لتأكيد الحذف. لا يُمسّ حساب الدخول أو بيانات المستخدم الأساسية.</p></div></section><section class="card"><div class="card-head"><div><h3>إنشاء أرشيف خاص</h3><p>أسبوعي للوثائق والصور، أو شهري للبيانات التشغيلية النصية.</p></div></div><form id="archive-form" class="report-controls"><label>النوع<select id="archive-kind"><option value="weekly_documents">وثائق وصور أسبوعية</option><option value="monthly_text">بيانات تشغيلية شهرية</option></select></label><label>من<input id="archive-start" type="date" value="${today}" required /></label><label>إلى<input id="archive-end" type="date" value="${today}" required /></label><button class="primary-button" type="submit">إنشاء PDF خاص</button></form></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>سجل الأرشيفات</h3><p>لا يظهر زر الحذف إلا بعد تسجيل تنزيل PDF.</p></div></div><div class="action-list">${archives.map((archive) => `<div class="action-item"><i class="round-icon ${archive.status === "purged" ? "amber" : "green"}">PDF</i><div><strong>${archive.archive_kind === "weekly_documents" ? "وثائق أسبوعية" : "بيانات شهرية"}</strong><span>${escapeHtml(archive.period_start)} ← ${escapeHtml(archive.period_end)} · ${statusLabel(archive.status)}</span></div>${archive.status !== "purged" ? `<button class="download-link" data-manual-download="${escapeHtml(archive.id)}">تنزيل PDF</button>${archive.downloaded_at ? `<button class="small-action" data-manual-purge="${escapeHtml(archive.id)}">حذف البيانات المؤرشفة</button>` : ""}` : `<span class="badge warning">حُذف بعد تأكيد</span>`}</div>`).join("") || `<p class="empty">لا توجد أرشيفات يدوية حتى الآن.</p>`}</div></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

async function renderRelease() { showLoading(); try { const result = await api("/admin/api/release-settings"); const settings = result.settings || {}; content.innerHTML = `<section class="hero"><div><p class="eyebrow">إدارة الإصدار</p><h2>تحديث التطبيق</h2><p>عند التفعيل، تمنع النسخ الأقدم من استخدام التطبيق وتفتح رابط التحديث الذي تحدده هنا.</p></div></section><section class="card"><form id="release-form" class="report-controls"><label>أقل إصدار مسموح<input id="release-version" pattern="\\d+\\.\\d+\\.\\d+" placeholder="1.0.1" value="${escapeHtml(settings.minVersion || "")}" /></label><label>رابط التحديث<input id="release-url" type="url" placeholder="https://..." value="${escapeHtml(settings.updateUrl || "")}" /></label><label class="checkbox-label"><input id="release-force" type="checkbox" ${settings.forceUpdate ? "checked" : ""} /> فرض التحديث</label><button class="primary-button" type="submit">حفظ إعداد الإصدار</button></form><p class="security-note">لا تفعّل الإيقاف الإلزامي قبل نشر النسخة الجديدة فعلياً وتأكيد رابط تنزيلها.</p></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }

function renderNotifications() { const list = $("#notification-list"); list.innerHTML = state.notifications.map((item) => `<div class="notification-entry"><i class="notice-dot ${item.level}"></i><div class="notice-copy"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.detail)} · ${dateLabel(item.createdAt)}</span></div></div>`).join("") || `<p class="empty">لا توجد تنبيهات جديدة.</p>`; const count = $("#notification-count"); count.textContent = String(state.notifications.length); count.classList.toggle("visible", state.notifications.length > 0); }
function bindContentActions() { document.querySelectorAll("[data-view-link]").forEach((button) => button.addEventListener("click", () => activateView(button.dataset.viewLink))); document.querySelectorAll("[data-action='open-notices']").forEach((button) => button.addEventListener("click", openNotifications)); const generator = $("#generate-report"); if (generator) generator.addEventListener("click", generateReport); const reportMonth = $("#report-month"); if (reportMonth) reportMonth.addEventListener("change", () => { state.reportMonth = reportMonth.value || null; renderReports(); }); document.querySelectorAll("[data-report-id]").forEach((button) => button.addEventListener("click", () => downloadReport(button.dataset.reportId, button))); document.querySelectorAll("[data-verification-id]").forEach((button) => button.addEventListener("click", () => sendVerificationCode(button.dataset.verificationId, button))); document.querySelectorAll("[data-recovery-id]").forEach((button) => button.addEventListener("click", () => sendRecoveryCode(button.dataset.recoveryId, button))); document.querySelectorAll("[data-pending-document]").forEach((button) => button.addEventListener("click", () => previewPendingDocument(button.dataset.requestId, button.dataset.pendingDocument))); document.querySelectorAll("[data-account-document]").forEach((button) => button.addEventListener("click", () => previewAccountDocument(button.dataset.accountId, button.dataset.accountDocument))); document.querySelectorAll("[data-account-toggle]").forEach((button) => button.addEventListener("click", () => toggleAccount(button.dataset.accountToggle, button.dataset.accountActive === "true"))); document.querySelectorAll("[data-discount-toggle]").forEach((button) => button.addEventListener("click", () => toggleDiscount(button.dataset.discountToggle, button.dataset.discountActive === "true"))); document.querySelectorAll("[data-manual-download]").forEach((button) => button.addEventListener("click", () => downloadManualArchive(button.dataset.manualDownload, button))); document.querySelectorAll("[data-manual-purge]").forEach((button) => button.addEventListener("click", () => purgeManualArchive(button.dataset.manualPurge))); document.querySelectorAll("[data-fill-outstanding]").forEach((button) => button.addEventListener("click", () => { const form = button.closest("form"); const input = form?.querySelector("[name='amount']"); if (input) input.value = button.dataset.fillOutstanding || ""; })); document.querySelectorAll(".driver-payment-form").forEach((form) => form.addEventListener("submit", recordDriverCompanyPayment)); const discountForm = $("#discount-form"); if (discountForm) discountForm.addEventListener("submit", createDiscount); const archiveForm = $("#archive-form"); if (archiveForm) archiveForm.addEventListener("submit", generateManualArchive); const releaseForm = $("#release-form"); if (releaseForm) releaseForm.addEventListener("submit", saveRelease); }
function rememberGeneratedCode(result) { const code = String(result.verificationCode || ""); if (!/^\d{6}$/.test(code)) throw new Error("VERIFICATION_CODE_UNAVAILABLE"); state.generatedVerification = { code, whatsappUrl: String(result.whatsappUrl || ""), expiresAt: result.expiresAt || null }; }
async function sendVerificationCode(requestId, button) { button.disabled = true; button.textContent = "جارٍ توليد الرمز…"; try { const result = await api(`/admin/api/verifications/${encodeURIComponent(requestId)}/send-code`, { method:"POST", body:"{}" }); rememberGeneratedCode(result); await renderVerificationWorkspace(); notify("تم توليد الرمز وظهر في البطاقة أعلى الصفحة. WhatsApp لن يُفتح إلا عند الضغط على زره."); } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "توليد رمز جديد"; } }
async function sendRecoveryCode(requestId, button) { button.disabled = true; button.textContent = "جارٍ توليد الرمز…"; try { const result = await api(`/admin/api/recovery-requests/${encodeURIComponent(requestId)}/send-code`, { method:"POST", body:"{}" }); rememberGeneratedCode(result); await renderVerificationWorkspace(); notify("تم توليد رمز الاسترجاع وظهر في البطاقة أعلى الصفحة. WhatsApp لن يُفتح إلا عند الضغط على زره."); } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "توليد رمز الاسترجاع"; } }
async function previewPendingDocument(requestId, kind) { try { const result = await api(`/admin/api/verifications/${encodeURIComponent(requestId)}/document/${encodeURIComponent(kind)}`); window.open(result.url, "_blank", "noopener,noreferrer"); } catch (error) { handleApiError(error); } }
async function previewAccountDocument(accountId, kind) { try { const result = await api(`/admin/api/accounts/${encodeURIComponent(accountId)}/document/${encodeURIComponent(kind)}`); window.open(result.url, "_blank", "noopener,noreferrer"); } catch (error) { handleApiError(error); } }
async function toggleAccount(accountId, active) { const action = active ? "إيقاف" : "إعادة تفعيل"; if (!window.confirm(`${action} هذا الحساب؟ لا يحذف الإجراء بيانات الدخول الأساسية.`)) return; try { await api(`/admin/api/accounts/${encodeURIComponent(accountId)}/${active ? "deactivate" : "reactivate"}`, { method:"POST", body:"{}" }); notify(active ? "تم إيقاف الحساب ومنع دخوله." : "تمت إعادة تفعيل الحساب."); await renderAccounts(); } catch (error) { handleApiError(error); } }
async function deleteAccount(accountId) { const confirmation = window.prompt("هذا حذف نهائي للحساب ولكل طلباته وصوره ووثائقه. سيُحرر الرقم لإعادة التسجيل ولا يمكن استرجاع الطلبات المحذوفة. اكتب DELETE للحذف."); if (confirmation !== "DELETE") return; try { await api(`/admin/api/accounts/${encodeURIComponent(accountId)}`, { method:"DELETE", body:JSON.stringify({ confirmation:"DELETE_ACCOUNT" }) }); notify("حُذف الحساب وطلباته ووثائقه، وحُرر الرقم لتسجيل جديد."); await renderAccounts(); } catch (error) { handleApiError(error); } }
async function createDiscount(event) { event.preventDefault(); const body = { code: $("#discount-code").value.trim().toUpperCase(), discountType: $("#discount-type").value, discountValue: Number($("#discount-value").value), startsAt: $("#discount-start").value ? new Date($("#discount-start").value).toISOString() : null, endsAt: $("#discount-end").value ? new Date($("#discount-end").value).toISOString() : null }; try { await api("/admin/api/discounts", { method:"POST", body:JSON.stringify(body) }); notify("تم حفظ رمز الخصم. سيُراجع على الخادم عند طلب العميل."); await renderDiscounts(); } catch (error) { handleApiError(error); } }
async function toggleDiscount(codeId, active) { try { await api(`/admin/api/discounts/${encodeURIComponent(codeId)}/toggle`, { method:"POST", body:JSON.stringify({ isActive: !active }) }); notify(active ? "تم إيقاف رمز الخصم." : "تم تفعيل رمز الخصم."); await renderDiscounts(); } catch (error) { handleApiError(error); } }
async function recordDriverCompanyPayment(event) { event.preventDefault(); const form = event.currentTarget; const amount = Number(form.querySelector("[name='amount']").value); const note = form.querySelector("[name='note']").value.trim() || null; const driverId = form.dataset.driverId; if (!Number.isInteger(amount) || amount <= 0 || !driverId) return notify("أدخل مبلغاً صحيحاً أكبر من صفر.", true); if (!window.confirm(`تأكيد استلام ${money(amount)} نقداً من السفير؟ سيُخصم هذا المبلغ من رصيده المستحق للشركة.`)) return; const button = form.querySelector("button[type='submit']"); button.disabled = true; button.textContent = "جارٍ التسجيل…"; try { await api(`/admin/api/driver-company-balances/${encodeURIComponent(driverId)}/payments`, { method:"POST", body:JSON.stringify({ amount, paymentMethod:"cash", paymentReference:null, note }) }); notify("تم تسجيل استلام المبلغ النقدي. أُعيد حساب الرصيد المتبقي للسفير."); await renderSettlements(); } catch (error) { if (error.status === 409) notify("المبلغ أعلى من الرصيد المتبقي. حدّث الشاشة ثم أدخل القيمة الصحيحة.", true); else handleApiError(error); button.disabled = false; button.textContent = "تأكيد استلام Cash"; } }
async function generateManualArchive(event) { event.preventDefault(); const body = { archiveKind: $("#archive-kind").value, periodStart: $("#archive-start").value, periodEnd: $("#archive-end").value }; try { await api("/admin/api/manual-archives/generate", { method:"POST", body:JSON.stringify(body) }); notify("تم إنشاء ملف PDF الخاص. نزّله ثم أكّد الحذف يدوياً عند الحاجة."); await renderArchives(); } catch (error) { handleApiError(error); } }
async function downloadManualArchive(archiveId, button) { button.disabled = true; try { const result = await api(`/admin/api/manual-archives/${encodeURIComponent(archiveId)}/download`, { method:"POST", body:"{}" }); const anchor = document.createElement("a"); anchor.href = result.url; anchor.download = ""; anchor.rel = "noopener"; document.body.appendChild(anchor); anchor.click(); anchor.remove(); notify("بدأ تنزيل PDF وسُجل التأكيد. أصبح الحذف اليدوي متاحاً لهذا الأرشيف."); await renderArchives(); } catch (error) { handleApiError(error); button.disabled = false; } }
async function purgeManualArchive(archiveId) { const confirmation = window.prompt("هذا إجراء لا يمكن التراجع عنه: اكتب DELETE بعد التأكد من تنزيل ملف PDF."); if (confirmation !== "DELETE") return; try { const result = await api(`/admin/api/manual-archives/${encodeURIComponent(archiveId)}/purge`, { method:"POST", body:JSON.stringify({ confirmation }) }); notify(`تم الحذف اليدوي المؤكد: ${JSON.stringify(result.deleted)}`); await renderArchives(); } catch (error) { handleApiError(error); } }
async function saveRelease(event) { event.preventDefault(); const body = { minVersion: $("#release-version").value.trim() || null, updateUrl: $("#release-url").value.trim() || null, forceUpdate: $("#release-force").checked }; if (body.forceUpdate && !window.confirm("تأكد أن النسخة الجديدة منشورة وأن رابطها صحيح. هل تريد فرض التحديث الآن؟")) return; try { await api("/admin/api/release-settings", { method:"PUT", body:JSON.stringify(body) }); notify(body.forceUpdate ? "تم تفعيل التحديث الإلزامي للنسخ الأقدم." : "تم حفظ إعداد الإصدار دون فرض إيقاف."); await renderRelease(); } catch (error) { handleApiError(error); } }
async function generateReport() { const input = $("#report-month"); const button = $("#generate-report"); const value = input.value ? `${input.value}-01` : ""; button.disabled = true; button.textContent = "جارٍ الإنشاء…"; try { const response = await api("/admin/api/reports/generate", { method:"POST", body:JSON.stringify({ reportMonth:value }) }); notify(response.result?.generated ? "تم إنشاء التقرير، وهو الآن جاهز للتحميل." : "تمت مراجعة حالة التقرير. قد يكون موجوداً بالفعل."); await renderReports(); } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "إنشاء أو تحديث التقرير"; } }
async function downloadReport(reportId, button) { button.disabled = true; button.textContent = "جارٍ التحضير…"; try { const response = await api(`/admin/api/reports/${encodeURIComponent(reportId)}/download`, { method:"POST", body:"{}" }); const anchor = document.createElement("a"); anchor.href = response.url; anchor.download = ""; anchor.rel = "noopener"; document.body.appendChild(anchor); anchor.click(); anchor.remove(); notify("بدأ تنزيل ملف PDF. تم تسجيل تأكيد التنزيل في سجل التقرير."); button.textContent = "تم التحميل"; } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "تنزيل PDF"; } }
async function refreshDashboard() { try { state.dashboard = await api("/admin/api/dashboard"); state.notifications = state.dashboard.notifications || []; renderNotifications(); if (state.currentView === "overview") renderOverview(); if (state.currentView === "operations") renderOperations(); } catch (error) { handleApiError(error); } }
function openNotifications() { $("#notification-drawer").hidden = false; renderNotifications(); }
function subscribeNotifications() { if (state.source) state.source.close(); state.source = new EventSource("/admin/api/notifications/stream"); state.source.addEventListener("notifications", (event) => { state.notifications = JSON.parse(event.data); renderNotifications(); if (state.currentView === "overview") renderOverview(); }); state.source.addEventListener("error", () => { window.setTimeout(refreshDashboard, 1200); }); }
async function login(event) { event.preventDefault(); const button = $("#login-button"); const errorBox = $("#login-error"); const password = $("#password").value; const body = { password }; button.disabled = true; button.textContent = "جارٍ التحقق…"; errorBox.hidden = true; try { const result = await api("/admin/api/login", { method:"POST", body:JSON.stringify(body) }); state.user = result.user; await openAdmin(); } catch (error) { errorBox.textContent = error.status === 401 ? "كلمة المرور غير صحيحة." : error.status === 429 ? "تم إيقاف المحاولة مؤقتاً للحماية. حاول لاحقاً." : error.status === 503 ? "إعداد كلمة المرور في الموقع غير مكتمل. أعد المحاولة بعد لحظات." : "تعذر الاتصال ببوابة الإدارة. حاول مرة أخرى."; errorBox.hidden = false; } finally { button.disabled = false; button.textContent = "فتح الموقع"; } }
function showSetup() { loginForm.hidden = true; setupForm.hidden = false; loginView.hidden = false; $("#setup-password").focus(); }
async function setup(event) { event.preventDefault(); const button = $("#setup-button"); const errorBox = $("#setup-error"); const password = $("#setup-password").value; const confirmation = $("#setup-confirmation").value; errorBox.hidden = true; if (password.length < 16) { errorBox.textContent = "استخدم كلمة مرور بطول 16 حرفاً على الأقل."; errorBox.hidden = false; return; } if (password !== confirmation) { errorBox.textContent = "كلمتا المرور غير متطابقتين."; errorBox.hidden = false; return; } button.disabled = true; button.textContent = "جارٍ حفظ القفل…"; try { const result = await api("/admin/api/setup", { method:"POST", body:JSON.stringify({ password, confirmation }) }); state.user = result.user; await openAdmin(); } catch (error) { errorBox.textContent = error.status === 409 ? "تمت تهيئة الموقع بالفعل. حدّث الصفحة ثم استخدم كلمة المرور." : "تعذر حفظ كلمة المرور الآن. أعد المحاولة."; errorBox.hidden = false; } finally { button.disabled = false; button.textContent = "حفظ كلمة المرور وفتح الموقع"; } }
async function openAdmin() { loginView.hidden = true; adminView.hidden = false; $("#manager-name").textContent = state.user.name || "مدير جربوع"; $("#manager-initial").textContent = (state.user.name || "م").slice(0,1); await refreshDashboard(); subscribeNotifications(); }
async function logout() { try { await api("/admin/api/logout", { method:"POST", body:"{}" }); } finally { if (state.source) state.source.close(); state.source = null; adminView.hidden = true; loginView.hidden = false; $("#password").value = ""; notify("تم تسجيل الخروج بأمان."); } }
function handleApiError(error) { if (error.status === 401 || error.status === 403) { logout(); return; } notify("تعذر تنفيذ الطلب الآن. تحقق من الاتصال أو من حالة الخدمة.", true); }
async function consumeRecoveryFragment() { const match = /^#recover=([a-f0-9]{64})$/.exec(window.location.hash); if (!match) return false; const errorBox = $("#login-error"); loginView.hidden = false; errorBox.hidden = true; try { await api("/admin/api/recover", { method:"POST", body:JSON.stringify({ token: match[1] }) }); window.history.replaceState(null, "", "/admin"); const result = await api("/admin/api/session"); state.user = result.user; await openAdmin(); return true; } catch { window.history.replaceState(null, "", "/admin"); errorBox.textContent = "رابط الاسترداد غير صالح أو تم استخدامه أو انتهت صلاحيته."; errorBox.hidden = false; return true; } }
loginForm.addEventListener("submit", login); setupForm.addEventListener("submit", setup); $("#logout-button").addEventListener("click", logout); $("#notification-button").addEventListener("click", openNotifications); $("#close-notifications").addEventListener("click", () => { $("#notification-drawer").hidden = true; }); $("#sidebar-nav").addEventListener("click", (event) => { const button = event.target.closest("[data-view]"); if (button) activateView(button.dataset.view); });

async function renderFleetMap() { showLoading(); try { const payload = await api("/admin/api/fleet-map"); const drivers = payload.drivers || []; const onMission = drivers.filter((driver) => driver.activeOrder); content.innerHTML = `<section class="hero"><div><p class="eyebrow">حماة · متابعة مباشرة</p><h2>خريطة الأسطول الحية</h2><p>اضغط على علامة أي سفير لعرض آخر موقعه، مسار الرحلة الفعلي، نقطة الاستلام والوجهة، المدة والتكلفة التقديرية.</p></div><span class="badge success">${arabicNumber(drivers.length)} سفراء مفعّلون</span></section><section class="fleet-layout"><article class="card"><div class="map-toolbar"><label>تصفية النقاط<select id="fleet-map-filter"><option value="all">الكل</option><option value="drivers">السفراء فقط</option><option value="customers">العملاء فقط</option></select></label><span class="map-key"><i class="map-key-driver">س</i> سفراء <i class="map-key-customer">ع</i> عملاء</span><span class="map-live-badge">تحديث حي</span></div><div id="fleet-map" class="map-panel fleet-map"></div><p class="data-note">تقتصر هذه البيانات التشغيلية على بوابة الإدارة المحمية، وتُحدَّث مواقع النقاط تلقائياً كل ثلاث ثوانٍ عند فتح الخريطة دون إعادة تحميل الصفحة.</p></article><aside class="card fleet-summary"><div class="card-head"><div><h3>السفراء على الخريطة</h3><p>الرحلات النشطة تظهر مع مسارها.</p></div><span class="badge ${onMission.length ? "success" : ""}">${arabicNumber(onMission.length)} رحلة</span></div>${drivers.map((driver) => `<div class="action-item" data-fleet-driver="${escapeHtml(driver.id)}"><i class="round-icon ${driver.activeOrder ? "green" : ""}">${escapeHtml((driver.name || "س").slice(0,1))}</i><div><strong>${escapeHtml(driver.name || "سفير جربوع")}</strong><span>${driver.activeOrder ? `${escapeHtml(driver.activeOrder.sourceAddress)} ← ${escapeHtml(driver.activeOrder.destinationAddress)}` : driver.lastLocationAt ? `آخر موقع: ${dateLabel(driver.lastLocationAt)}` : "لم يرسل موقعاً بعد"}</span></div><span class="badge ${driver.activeOrder ? "success" : ""}">${driver.activeOrder ? money(driver.activeOrder.estimatedPrice) : "متاح"}</span></div>`).join("") || `<p class="empty">لا توجد حسابات سفراء مفعلة بعد.</p>`}<p class="fleet-route-note">الموقع يعتمد على آخر GPS موثوق من تطبيق السفير. إذا لم يظهر سفير على الخريطة، فهذا يعني أنه لم يرسل موقعاً حديثاً بعد.</p></aside></section>`; if (typeof window.installFleetOperationsMap === "function") window.installFleetOperationsMap(payload); bindContentActions(); } catch (error) { handleApiError(error); } }
async function renderAccountSearch() { content.innerHTML = `<section class="hero"><div><p class="eyebrow">وصول سريع</p><h2>بحث الحسابات</h2><p>ابحث بالاسم أو رقم WhatsApp للعميل أو السفير. الاسم المكرر مسموح، والرقم هو المعرّف الفريد.</p></div></section><section class="card"><form id="account-search-form" class="search-form"><label>الاسم أو الرقم<input id="account-search-query" minlength="2" placeholder="مثال: أحمد أو +9639…" required /></label><button class="primary-button" type="submit">بحث</button></form><div id="account-search-results" class="action-list" style="margin-top:16px"><p class="empty">اكتب الاسم أو الرقم ثم اضغط بحث.</p></div></section>`; bindContentActions(); }
async function searchAccounts(event) { event.preventDefault(); const query = $("#account-search-query").value.trim(); const results = $("#account-search-results"); if (query.length < 2) return notify("اكتب حرفين أو رقمين على الأقل للبحث.", true); results.innerHTML = `<p class="empty">جارٍ البحث…</p>`; try { const response = await api(`/admin/api/accounts/search?q=${encodeURIComponent(query)}`); const accounts = response.accounts || []; results.innerHTML = accounts.map((account) => { const isManualDriver = account.record_type === "manual_driver"; const label = isManualDriver ? "سفير مضاف يدوياً" : account.role === "driver" ? "سفير" : "عميل"; const status = isManualDriver ? (account.claimed_at ? "بدأ التسجيل" : "بانتظار التسجيل") : account.is_active ? "نشط" : "موقوف"; return `<div class="action-item"><i class="round-icon ${account.role === "driver" ? "green" : ""}">${account.role === "driver" ? "س" : "ع"}</i><div><strong>${escapeHtml(account.name)} · ${label}</strong><span>${escapeHtml(account.phone || "—")} · ${isManualDriver ? "يمكنه إكمال التسجيل من التطبيق بهذا الرقم" : dateLabel(account.created_at)}</span></div><span class="badge ${isManualDriver ? "warning" : account.is_active ? "success" : "warning"}">${status}</span></div>`; }).join("") || `<p class="empty">لا توجد نتيجة مطابقة للاسم أو الرقم.</p>`; } catch (error) { handleApiError(error); } }
async function renderDriverInvites() { showLoading(); try { const response = await api("/admin/api/driver-invites"); const invites = response.invites || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">فريق جربوع</p><h2>إضافة سفير إلى الفريق</h2><p>احفظ بيانات السفير ثم أرسل له التطبيق. يدخل بالرقم نفسه، يفعّل حساب الفريق برمز WhatsApp، ويختار كلمة مروره بنفسه.</p></div></section><section class="reports-layout"><article class="card"><div class="card-head"><div><h3>بيانات سفير جديد</h3><p>رقم الهاتف فريد ولا يمكن استخدامه لحساب آخر.</p></div></div><form id="driver-invite-form" class="report-controls"><label>الاسم الحقيقي<input name="fullName" required maxlength="100" placeholder="الاسم من كلمتين إن أمكن" /></label><label>رقم WhatsApp<input name="phone" required inputmode="tel" placeholder="+9639…" /></label><label>المركبة<select name="vehicleType"><option value="">غير محدد</option><option value="motorcycle">دراجة نارية</option><option value="electric_scooter">دراجة كهربائية</option></select></label><label>ملاحظة (اختيارية)<input name="note" maxlength="500" placeholder="مثال: مرشح للعمل" /></label><button class="primary-button" type="submit">إضافة إلى الفريق</button></form></article><article class="card"><div class="card-head"><div><h3>سفراء الفريق المضافون</h3><p>تظهر «جاهز للتفعيل» إلى أن يفتح السفير التطبيق ويكمل تأكيد الرقم وكلمة المرور.</p></div><span class="badge">${arabicNumber(invites.length)} سجلات</span></div><div class="invite-list">${invites.map((invite) => `<div class="action-item"><i class="round-icon green">س</i><div><strong>${escapeHtml(invite.full_name)}</strong><span>${escapeHtml(invite.phone)} · ${invite.vehicle_type === "motorcycle" ? "دراجة نارية" : invite.vehicle_type === "electric_scooter" ? "دراجة كهربائية" : "مركبة غير محددة"}${invite.note ? ` · ${escapeHtml(invite.note)}` : ""}</span></div><span class="badge ${invite.claimed_at ? "success" : "warning"}">${invite.claimed_at ? "قيد التفعيل" : "جاهز للتفعيل"}</span></div>`).join("") || `<p class="empty">لا توجد بيانات سفراء مضافة بعد.</p>`}</div></article></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }
async function createDriverInvite(event) { event.preventDefault(); const form = event.currentTarget; const body = { fullName: form.querySelector("[name='fullName']").value.trim(), phone: form.querySelector("[name='phone']").value.trim(), vehicleType: form.querySelector("[name='vehicleType']").value || null, note: form.querySelector("[name='note']").value.trim() || null }; const button = form.querySelector("button[type='submit']"); button.disabled = true; try { await api("/admin/api/driver-invites", { method:"POST", body:JSON.stringify(body) }); notify("تم حفظ بيانات السائق. أرسل له التطبيق ليكمل التسجيل بالرقم نفسه."); await renderDriverInvites(); } catch (error) { notify(error.status === 409 ? "هذا الرقم مستخدم في حساب قائم، ولا يمكن إضافته كسائق جديد." : "تعذر حفظ بيانات السائق الآن.", true); button.disabled = false; } }
async function renderProblemReports() { showLoading(); try { const response = await api("/admin/api/problem-reports"); const reports = response.reports || []; content.innerHTML = `<section class="hero"><div><p class="eyebrow">رسائل التطبيق</p><h2>بلاغات المشاكل</h2><p>تصل بلاغات العملاء والسفراء هنا، ثم تختار حالتها وتضيف ملاحظة إدارية إن لزم.</p></div><span class="badge warning">${arabicNumber(reports.filter((report) => report.status === "open").length)} مفتوحة</span></section><section class="card"><div class="action-list">${reports.map((report) => `<div class="action-item"><i class="round-icon ${report.reporter_role === "driver" ? "amber" : "green"}">${report.reporter_role === "driver" ? "س" : "ع"}</i><div><strong>${escapeHtml(report.reporter?.name || "حساب محذوف")} · ${report.reporter_role === "driver" ? "سفير" : "عميل"}</strong><span>${escapeHtml(report.message)} · ${dateLabel(report.created_at)}</span><form class="report-status-form" data-problem-id="${escapeHtml(report.id)}"><label>الحالة<select name="status"><option value="open" ${report.status === "open" ? "selected" : ""}>مفتوح</option><option value="reviewed" ${report.status === "reviewed" ? "selected" : ""}>قيد المراجعة</option><option value="resolved" ${report.status === "resolved" ? "selected" : ""}>تم الحل</option></select></label><label>ملاحظة الإدارة<textarea name="adminNote" maxlength="1000" placeholder="ملاحظة داخلية اختيارية">${escapeHtml(report.admin_note || "")}</textarea></label><button class="small-action" type="submit">حفظ المتابعة</button></form></div><span class="badge ${report.status === "resolved" ? "success" : report.status === "open" ? "warning" : ""}">${report.status === "resolved" ? "تم الحل" : report.status === "reviewed" ? "قيد المراجعة" : "مفتوح"}</span></div>`).join("") || `<p class="empty">لا توجد بلاغات مشاكل حالياً.</p>`}</div></section>`; bindContentActions(); } catch (error) { handleApiError(error); } }
async function updateProblemReport(event) { event.preventDefault(); const form = event.currentTarget; const reportId = form.dataset.problemId; const body = { status: form.querySelector("[name='status']").value, adminNote: form.querySelector("[name='adminNote']").value.trim() || null }; try { await api(`/admin/api/problem-reports/${encodeURIComponent(reportId)}`, { method:"POST", body:JSON.stringify(body) }); notify("تم حفظ حالة البلاغ وملاحظتك الإدارية."); await renderProblemReports(); } catch (error) { handleApiError(error); } }

function renderAdminSettings() { content.innerHTML = `<section class="hero"><div><p class="eyebrow">وصول خاص</p><h2>إعدادات الإدارة</h2><p>عيّن كلمة مرور جديدة للبوابة من هذه الجلسة فقط. لا يُطلب منك إدخال كلمة المرور الحالية.</p></div></section><section class="card"><form id="admin-password-form" class="report-controls"><label>كلمة المرور الجديدة<input id="admin-password" autocomplete="new-password" type="password" minlength="16" placeholder="16 حرفاً على الأقل" required /></label><label>تأكيد كلمة المرور الجديدة<input id="admin-password-confirmation" autocomplete="new-password" type="password" minlength="16" placeholder="أعد كتابة كلمة المرور" required /></label><button class="primary-button" type="submit">تعيين كلمة المرور الجديدة</button></form><p class="security-note">عند الحفظ تصبح هذه كلمة المرور المعتمدة للدخول إلى الرابط نفسه. لا تُحفظ كلمة المرور كنص ظاهر.</p></section>`; bindContentActions(); }
async function changeAdminPassword(event) { event.preventDefault(); const password = $("#admin-password").value; const confirmation = $("#admin-password-confirmation").value; if (password.length < 16) return notify("استخدم كلمة مرور بطول 16 حرفاً على الأقل.", true); if (password !== confirmation) return notify("كلمتا المرور غير متطابقتين.", true); const button = event.currentTarget.querySelector("button[type='submit']"); button.disabled = true; button.textContent = "جارٍ الحفظ…"; try { await api("/admin/api/password", { method:"POST", body:JSON.stringify({ password, confirmation }) }); event.currentTarget.reset(); notify("تم تعيين كلمة المرور الجديدة للرابط نفسه بنجاح."); } catch (error) { handleApiError(error); button.disabled = false; button.textContent = "تعيين كلمة المرور الجديدة"; } }
const baseRenderAccounts = renderAccounts;
renderAccounts = async function() { await baseRenderAccounts(); const description = content.querySelector(".hero p:last-child"); if (description) description.innerHTML = "<strong>إيقاف الحساب</strong> يمنع الدخول ويُبقي الحساب مسجلاً. أما <strong>حذف الحساب</strong> فيزيل بيانات الدخول والوثائق ويحرر الرقم للتسجيل من جديد."; document.querySelectorAll("[data-account-toggle]").forEach((toggleButton) => { const deleteButton = document.createElement("button"); deleteButton.type = "button"; deleteButton.className = "small-action"; deleteButton.dataset.accountDelete = toggleButton.dataset.accountToggle || ""; deleteButton.textContent = "حذف الحساب"; deleteButton.addEventListener("click", () => deleteAccount(deleteButton.dataset.accountDelete)); toggleButton.insertAdjacentElement("afterend", deleteButton); }); };
async function reviewDriverDocuments(accountId, decision) { const approved = decision === "approved"; if (!window.confirm(approved ? "اعتماد وثائق هذا السفير وتمكينه من تلقي الطلبات؟" : "رفض وثائق هذا السفير وإيقاف حسابه؟")) return; try { await api(`/admin/api/accounts/${encodeURIComponent(accountId)}/driver-verification`, { method:"POST", body:JSON.stringify({ decision }) }); notify(approved ? "تم اعتماد وثائق السفير. ستصل إليه الطلبات بعد تحديث موقعه." : "تم رفض وثائق السفير وإيقافه."); await renderAccounts(); } catch (error) { handleApiError(error); } }
const renderAccountsWithDriverReview = renderAccounts;
renderAccounts = async function() { await renderAccountsWithDriverReview(); document.querySelectorAll("[data-account-document]").forEach((button) => { button.textContent = button.dataset.accountDocument === "personal" ? "عرض الصورة الشخصية" : "عرض صورة الهوية"; }); document.querySelectorAll("[data-account-document='identity']").forEach((documentButton) => { const accountId = documentButton.dataset.accountId; const actions = documentButton.closest("tr")?.querySelector("[data-account-toggle]")?.parentElement; if (!accountId || !actions || actions.querySelector("[data-driver-review]")) return; const approve = document.createElement("button"); approve.type = "button"; approve.className = "small-action"; approve.dataset.driverReview = "approved"; approve.textContent = "اعتماد السفير"; approve.addEventListener("click", () => reviewDriverDocuments(accountId, "approved")); const reject = document.createElement("button"); reject.type = "button"; reject.className = "small-action"; reject.dataset.driverReview = "rejected"; reject.textContent = "رفض الوثائق"; reject.addEventListener("click", () => reviewDriverDocuments(accountId, "rejected")); actions.append(approve, reject); }); };
const baseActivateView = activateView;
activateView = function(view) { const extraTitles = { fleet:"خريطة الأسطول", "account-search":"بحث الحسابات", "driver-invites":"إضافة سائق", problems:"بلاغات المشاكل", "site-settings":"إعدادات الإدارة" }; if (!extraTitles[view]) return baseActivateView(view); state.currentView = view; document.querySelectorAll(".nav-link").forEach((item) => item.classList.toggle("active", item.dataset.view === view)); $("#page-title").textContent = extraTitles[view]; if (view === "fleet") renderFleetMap(); if (view === "account-search") renderAccountSearch(); if (view === "driver-invites") renderDriverInvites(); if (view === "problems") renderProblemReports(); if (view === "site-settings") renderAdminSettings(); };
const baseBindContentActions = bindContentActions;
bindContentActions = function() { baseBindContentActions(); const searchForm = $("#account-search-form"); if (searchForm) searchForm.addEventListener("submit", searchAccounts); const inviteForm = $("#driver-invite-form"); if (inviteForm) inviteForm.addEventListener("submit", createDriverInvite); const passwordForm = $("#admin-password-form"); if (passwordForm) passwordForm.addEventListener("submit", changeAdminPassword); document.querySelectorAll(".report-status-form").forEach((form) => form.addEventListener("submit", updateProblemReport)); };
const baseCreateDiscount = createDiscount;
createDiscount = async function(event) { event.preventDefault(); const body = { code: $("#discount-code").value.trim().toUpperCase(), discountType: $("#discount-type").value, discountValue: Number($("#discount-value").value), startsAt: $("#discount-start").value ? new Date($("#discount-start").value).toISOString() : null, endsAt: $("#discount-end").value ? new Date($("#discount-end").value).toISOString() : null, audience: state.discountAudience, customerIds: state.discountAudience === "selected" ? state.discountRecipients.map((customer) => customer.id) : [] }; try { await api("/admin/api/discounts", { method:"POST", body:JSON.stringify(body) }); state.discountAudience = "public"; state.discountRecipients = []; state.discountCustomerResults = []; notify(body.audience === "public" ? "تم حفظ العرض العام لجميع العملاء." : `تم حفظ العرض المخصص لـ ${arabicNumber(body.customerIds.length)} عملاء.`); await renderDiscounts(); } catch (error) { if (error.message === "DISCOUNT_RECIPIENT_NOT_AVAILABLE") notify("أحد العملاء المحددين لم يعد نشطاً. ابحث عنه مجدداً قبل الحفظ.", true); else handleApiError(error); } };
function discountRecipientSummary(code) { if (code.audience !== "selected") return "عرض عام لجميع العملاء"; const names = (code.recipients || []).map((customer) => customer.name).filter(Boolean); return `عرض مخصص لـ ${arabicNumber((code.recipients || []).length)}: ${escapeHtml(names.join("، ") || "عملاء محددين")}`; }
function bindDiscountRecipientActions() { const audience = $("#discount-audience"); if (audience) audience.addEventListener("change", () => { state.discountAudience = audience.value; if (state.discountAudience === "public") { state.discountRecipients = []; state.discountCustomerResults = []; } renderDiscounts(); }); const customerSearch = $("#discount-customer-search"); if (customerSearch) customerSearch.addEventListener("submit", async (event) => { event.preventDefault(); const query = $("#discount-customer-query").value.trim(); if (query.length < 2) return notify("اكتب حرفين أو رقمين على الأقل للبحث عن عميل.", true); const resultBox = $("#discount-customer-results"); resultBox.innerHTML = `<p class="empty">جارٍ البحث…</p>`; try { const result = await api(`/admin/api/discount-customers?q=${encodeURIComponent(query)}`); state.discountCustomerResults = (result.customers || []).filter((customer) => !state.discountRecipients.some((selected) => selected.id === customer.id)); if (!state.discountCustomerResults.length) resultBox.innerHTML = `<p class="empty">لا يوجد عميل نشط مطابق أو أنه محدد بالفعل.</p>`; else resultBox.innerHTML = state.discountCustomerResults.map((customer) => `<button type="button" class="text-button" data-discount-customer="${escapeHtml(customer.id)}">إضافة ${escapeHtml(customer.name)} · ${escapeHtml(customer.phone || "")}</button>`).join(""); document.querySelectorAll("[data-discount-customer]").forEach((button) => button.addEventListener("click", () => { const customer = state.discountCustomerResults.find((item) => item.id === button.dataset.discountCustomer); if (!customer) return; state.discountRecipients = [...state.discountRecipients, customer].slice(0, 50); state.discountCustomerResults = []; renderDiscounts(); })); } catch (error) { handleApiError(error); } }); document.querySelectorAll("[data-remove-discount-customer]").forEach((button) => button.addEventListener("click", () => { state.discountRecipients = state.discountRecipients.filter((customer) => customer.id !== button.dataset.removeDiscountCustomer); renderDiscounts(); })); }
renderDiscounts = async function() { showLoading(); try { const result = await api("/admin/api/discounts"); const codes = result.codes || []; const selected = state.discountRecipients || []; const isSelected = state.discountAudience === "selected"; content.innerHTML = `<section class="hero"><div><p class="eyebrow">عروض العملاء</p><h2>رموز الخصم</h2><p>أنشئ عرضاً عاماً، أو خصّصه لعملاء تختارهم بالاسم أو رقم WhatsApp. يُفرض الاستحقاق عند إنشاء الطلب.</p></div></section><section class="reports-layout"><article class="card"><div class="card-head"><div><h3>إنشاء عرض جديد</h3><p>العرض العام متاح لكل العملاء. العرض المخصص لا يقبله إلا العملاء المختارون أدناه.</p></div></div><form id="discount-form" class="report-controls"><label>نوع الاستحقاق<select id="discount-audience"><option value="public" ${!isSelected ? "selected" : ""}>عام لكل العملاء</option><option value="selected" ${isSelected ? "selected" : ""}>مخصص لعملاء محددين</option></select></label><label>الرمز<input id="discount-code" required maxlength="32" placeholder="JARBOU3" /></label><label>نوع الخصم<select id="discount-type"><option value="fixed">قيمة ثابتة</option><option value="percentage">نسبة مئوية</option></select></label><label>القيمة<input id="discount-value" type="number" min="1" step="1" required /></label><label>يبدأ (اختياري)<input id="discount-start" type="datetime-local" /></label><label>ينتهي (اختياري)<input id="discount-end" type="datetime-local" /></label>${isSelected ? `<div style="grid-column:1/-1" class="action-list"><div class="action-item"><div><strong>العملاء المختارون</strong><span>${selected.length ? "لن يتمكن من استخدام الرمز إلا هؤلاء العملاء." : "ابحث عن عميل واحد أو عدة عملاء ثم أضفهم."}</span></div><span class="badge warning">${arabicNumber(selected.length)} محددون</span></div>${selected.map((customer) => `<div class="action-item"><div><strong>${escapeHtml(customer.name)}</strong><span>${escapeHtml(customer.phone || "")}</span></div><button class="small-action" type="button" data-remove-discount-customer="${escapeHtml(customer.id)}">إزالة</button></div>`).join("")}<form id="discount-customer-search" class="search-form"><label>البحث عن عميل<input id="discount-customer-query" minlength="2" placeholder="الاسم أو رقم WhatsApp" required /></label><button class="small-action" type="submit">بحث وإضافة</button></form><div id="discount-customer-results" class="action-list"></div></div>` : ""}<button class="primary-button" type="submit">حفظ العرض</button></form></article><article class="card"><div class="card-head"><div><h3>العروض الحالية</h3><p>يمكن إيقاف أي عرض يدوياً في الحال.</p></div><span class="badge">${arabicNumber(codes.length)} عروض</span></div><div class="action-list">${codes.map((code) => `<div class="action-item"><i class="round-icon ${code.is_active ? "green" : "amber"}">٪</i><div><strong>${escapeHtml(code.code)} · ${code.discount_type === "percentage" ? `${arabicNumber(code.discount_value)}%` : money(code.discount_value)}</strong><span>${discountRecipientSummary(code)} · ${code.starts_at ? `يبدأ: ${dateLabel(code.starts_at)}` : "يبدأ فوراً"} · ${code.ends_at ? `ينتهي: ${dateLabel(code.ends_at)}` : "دون نهاية"}</span></div><button class="small-action" data-discount-toggle="${escapeHtml(code.id)}" data-discount-active="${code.is_active ? "true" : "false"}">${code.is_active ? "إيقاف" : "تفعيل"}</button></div>`).join("") || `<p class="empty">لا توجد عروض بعد.</p>`}</div></article></section>`; bindContentActions(); bindDiscountRecipientActions(); } catch (error) { handleApiError(error); } };
const baseBindDiscountRecipientActions = bindDiscountRecipientActions;
bindDiscountRecipientActions = function() { baseBindDiscountRecipientActions(); const input = $("#discount-customer-query"); const searchButton = input?.closest(".action-list")?.querySelector("button[type='submit']"); if (input && searchButton) searchButton.addEventListener("click", async (event) => { event.preventDefault(); const query = input.value.trim(); if (query.length < 2) return notify("اكتب حرفين أو رقمين على الأقل للبحث عن عميل.", true); const resultBox = $("#discount-customer-results"); resultBox.innerHTML = `<p class="empty">جارٍ البحث…</p>`; try { const result = await api(`/admin/api/discount-customers?q=${encodeURIComponent(query)}`); state.discountCustomerResults = (result.customers || []).filter((customer) => !state.discountRecipients.some((selected) => selected.id === customer.id)); resultBox.innerHTML = state.discountCustomerResults.length ? state.discountCustomerResults.map((customer) => `<button type="button" class="text-button" data-discount-customer="${escapeHtml(customer.id)}">إضافة ${escapeHtml(customer.name)} · ${escapeHtml(customer.phone || "")}</button>`).join("") : `<p class="empty">لا يوجد عميل نشط مطابق أو أنه محدد بالفعل.</p>`; document.querySelectorAll("[data-discount-customer]").forEach((button) => button.addEventListener("click", () => { const customer = state.discountCustomerResults.find((item) => item.id === button.dataset.discountCustomer); if (!customer) return; state.discountRecipients = [...state.discountRecipients, customer].slice(0, 50); state.discountCustomerResults = []; renderDiscounts(); })); } catch (error) { handleApiError(error); } }); };
window.setInterval(() => { if (!adminView.hidden && state.currentView === "fleet") { if (typeof window.refreshFleetOperationsMap === "function") window.refreshFleetOperationsMap(); else renderFleetMap(); } }, 3_000);
(async () => { if (await consumeRecoveryFragment()) return; try { const setupStatus = await api("/admin/api/setup-status"); if (setupStatus.setupRequired) { showSetup(); return; } const result = await api("/admin/api/session"); state.user = result.user; await openAdmin(); } catch { loginView.hidden = false; } })();
